#!/usr/bin/env bash
# Benchmark whisper.cpp models on this machine → docs/BENCHMARKS.md (real-time factor per model, with/without VAD).
# Uses the vendored whisper-cli and the test voices (tests/fixtures/media/voz_*.flac, generated by tools/make_test_media.sh).
# Usage: tools/bench_asr.sh [threads] [models...]   (default: nproc-1 threads, every model present in vendor/whisper/models)
set -uo pipefail
export LC_ALL=C   # decimal point, whatever the user's locale
ROOT="$(cd "$(dirname "$(readlink -f "$0")")/.." && pwd)"
cd "$ROOT"
BIN="${MPV_UOS_WHISPER_BIN:-$ROOT/vendor/whisper/bin}"
MODELS_DIR="${MPV_UOS_WHISPER_MODELS:-$ROOT/vendor/whisper/models}"
export LD_LIBRARY_PATH="$BIN${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}"
CLI="$BIN/whisper-cli"
[ -x "$CLI" ] || { echo "falta $CLI (tools/vendor_whisper.sh)"; exit 1; }
[ -f tests/fixtures/media/voz_es.flac ] || tools/make_test_media.sh
cpu=$(nproc)
threads="${1:-$(( cpu > 2 ? cpu - 1 : cpu ))}"; shift || true
if [ $# -gt 0 ]; then models=("$@"); else
  mapfile -t models < <(ls "$MODELS_DIR"/ggml-*.bin | sed 's#.*/ggml-##; s#\.bin$##' | grep -v '^silero' | sort)
fi
vad="$MODELS_DIR/ggml-silero-v5.1.2.bin"
TMP="$ROOT/tmp/bench"; mkdir -p "$TMP"
# 12 s sample (one chunk) and a ~34 s sample (es+en+es, longer than whisper's 30 s window)
ffmpeg -v error -y -i tests/fixtures/media/voz_es.flac -ac 1 -ar 16000 -c:a pcm_s16le "$TMP/es12.wav"
ffmpeg -v error -y -i tests/fixtures/media/voz_es.flac -i tests/fixtures/media/voz_en.flac -i tests/fixtures/media/voz_es.flac \
  -filter_complex "[0:a][1:a][2:a]concat=n=3:v=0:a=1[a]" -map "[a]" -ac 1 -ar 16000 -c:a pcm_s16le "$TMP/mix34.wav"
dur() { python3 -c "import os,sys;print(f'{(os.path.getsize(sys.argv[1])-44)/32000:.1f}')" "$1"; }
d12=$(dur "$TMP/es12.wav"); d34=$(dur "$TMP/mix34.wav")
model_cpu=$(grep -m1 'model name' /proc/cpuinfo | cut -d: -f2- | sed 's/^ *//')
mem=$(awk '/MemTotal/ {printf "%.0f", $2/1048576}' /proc/meminfo)

score() { # score <json> → "keywords_hit/7|text"
  python3 - "$1" <<'PY'
import json, sys, unicodedata
d = json.load(open(sys.argv[1]))
text = " ".join(r.get("text", "") for r in d.get("transcription", [])).strip()
def fold(s): return "".join(c for c in unicodedata.normalize("NFD", s.lower()) if unicodedata.category(c) != "Mn")
kws = ["bienvenido", "reproductor", "futuro", "zorro", "perro", "pelicula", "subtitulos"]
hit = sum(1 for k in kws if k in fold(text))
print(f"{hit}/7|{d.get('result', {}).get('language', '?')}|{text[:110]}")
PY
}

run() { # run <model> <wav> <lang> <vad yes/no> → "elapsed|score"
  local m="$1" wav="$2" lang="$3" usevad="$4" extra=() out="$TMP/out"
  [ "$usevad" = yes ] && [ -f "$vad" ] && extra=(--vad --vad-model "$vad")
  rm -f "$out.json"
  local s e; s=$(date +%s.%N)
  "$CLI" -m "$MODELS_DIR/ggml-$m.bin" -f "$wav" -t "$threads" -l "$lang" -oj -of "$out" -np "${extra[@]}" >/dev/null 2>&1
  e=$(date +%s.%N)
  printf '%.2f|%s\n' "$(echo "$e - $s" | bc)" "$( [ -f "$out.json" ] && score "$out.json" || echo '0/7|?|(fallo)')"
}

OUT="docs/BENCHMARKS.md"
{
  echo "# Benchmarks de ASR (whisper.cpp)"
  echo
  echo "Generado por \`tools/bench_asr.sh\` el $(date +%F) en \`$(hostname)\`: $model_cpu, $cpu núcleos, $mem GB RAM, sin GPU dedicada."
  echo "whisper.cpp: $("$CLI" --version 2>&1 | head -1) · hilos: $threads · muestras: voz sintética espeak-ng (tests/fixtures/media)."
  echo
  echo "RTF = tiempo de proceso / duración del audio (menor es mejor). \"Palabras\" = palabras clave del manifiesto reconocidas (de 7)."
  echo "El coste por llamada tiene una parte fija (encoder sobre la ventana de 30 s), por eso el RTF mejora con trozos más largos."
  echo
  echo "| Modelo | Tamaño | es 12 s, -l es | es 12 s, -l es + VAD | mezcla ${d34} s, -l auto + VAD | Palabras (12 s) | Idioma detectado (mezcla) |"
  echo "|---|---|---|---|---|---|---|"
} > "$OUT.tmp"
for m in "${models[@]}"; do
  [ -f "$MODELS_DIR/ggml-$m.bin" ] || { echo "no está: $m"; continue; }
  echo "▶ $m"
  size=$(du -m "$MODELS_DIR/ggml-$m.bin" | cut -f1)
  r1=$(run "$m" "$TMP/es12.wav" es no);   t1=${r1%%|*}; s1=${r1#*|}; k1=${s1%%|*}
  r2=$(run "$m" "$TMP/es12.wav" es yes);  t2=${r2%%|*}
  r3=$(run "$m" "$TMP/mix34.wav" auto yes); t3=${r3%%|*}; s3=${r3#*|}; l3=$(echo "$s3" | cut -d"|" -f2)
  rtf() { python3 -c "import sys;print(f'{float(sys.argv[1])/float(sys.argv[2]):.2f}')" "$1" "$2"; }
  echo "| $m | ${size} MB | ${t1} s (RTF $(rtf "$t1" "$d12")) | ${t2} s (RTF $(rtf "$t2" "$d12")) | ${t3} s (RTF $(rtf "$t3" "$d34")) | $k1 | $l3 |" >> "$OUT.tmp"
  echo "   12s: ${t1}s / vad ${t2}s · mezcla: ${t3}s · palabras $k1 · idioma $l3"
done
{
  echo
  echo "## Lectura"
  echo "- En vivo (mientras mpv decodifica) se exige RTF ≤ 0,5 con trozos de 20 s; para pre-subtitular (baja prioridad) basta RTF < 1."
  echo "- Con voz sintética el modelo tiny confunde el idioma en modo \`auto\`; con el idioma fijado acierta. base ya reconoce casi todas las"
  echo "  palabras clave; small es claramente mejor pero solo cabe en vivo con más núcleos o GPU."
  echo "- El FLAC leído directamente por whisper-cli (miniaudio) devolvió vacío en esta versión: mpvd siempre pasa WAV 16 kHz mono extraído con ffmpeg."
  echo "- Los cuantizados q5_1 son MÁS lentos que q8_0 y que el modelo completo en esta CPU (sin AVX-512); solo ahorran disco."
  echo "- Tabla de elección por tier (mpvd/asr/models.py): small (≤4 núcleos) → en vivo base, pre-cálculo base · medium → base / small-q8_0 ·"
  echo "  large → small-q8_0 / small. El usuario puede forzar otro modelo desde el menú Subtítulos IA → Modelo."
} >> "$OUT.tmp"
mv "$OUT.tmp" "$OUT"
echo "→ $OUT"
